export function getLogoList(): LogoEntry[] {
  return Object.entries(LOGO_MAP).map(([slug, { label, svg }]) => ({
    slug,
    label,
    svg,
  }));
}

export function getLogoSvg(slug: string): string | undefined {
  return LOGO_MAP[slug]?.svg;
}

export function getLogoSlugBySvg(svg: string): string | undefined {
  const entry = Object.entries(LOGO_MAP).find(([, v]) => v.svg === svg);
  return entry?.[0];
}
